    PRIMARY KEY ("id")
);
CREATE TABLE "fill_action_events" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "fill_run_id" TEXT NOT NULL,
    "action_index" BIGINT NOT NULL,
    "event" TEXT NOT NULL,
    "outcome" TEXT,
    "envelope_id" TEXT,
    "readback_hash" TEXT,
    "detail_json" TEXT NOT NULL DEFAULT '{}',
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("id"),
    CHECK (action_index >= 0),
    CHECK (event IN ('PRECHECK', 'WRITE_INTENT', 'ENVELOPE_ISSUED', 'OUTCOME')),
    CHECK (outcome IS NULL OR outcome IN ('WRITTEN_VERIFIED', 'NOOP_ALREADY_EQUAL', 'OMIT_VERIFIED', 'IGNORE_RECORDED', 'ATTACH_LOCAL_VERIFIED', 'READBACK_MISMATCH', 'TARGET_CHANGED', 'FIELD_VALIDITY_FAILED', 'FIELD_VALUE_REVERTED', 'ATTACH_LOCAL_MISMATCH', 'WRITE_OUTCOME_UNKNOWN', 'ENVELOPE_EXPIRED')),
    CHECK ((event = 'OUTCOME') = (outcome IS NOT NULL))
);
CREATE TABLE "fill_detection_events" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "fill_run_id" TEXT NOT NULL,
    "kind" TEXT NOT NULL,
    "detail_json" TEXT NOT NULL DEFAULT '{}',
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("id"),
    CHECK (kind IN ('SUBMIT_ATTEMPT_OBSERVED', 'NAVIGATION_ATTEMPT_OBSERVED', 'POST_FILL_CHANGE_OBSERVED', 'EXECUTION_CONTEXT_CLOSED'))
);
CREATE TABLE "fill_observations" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "account_id" TEXT NOT NULL,
    "application_workspace_id" TEXT NOT NULL,
    "fill_run_id" TEXT,
    "phase" TEXT NOT NULL,
    "action_index" BIGINT,
    "structure_fingerprint" TEXT NOT NULL,
    "observation_fingerprint" TEXT NOT NULL,
    "observation_json" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("id"),
    CHECK (phase IN ('INITIAL', 'REVALIDATION', 'PRE_ACTION', 'POST_ACTION', 'FINAL', 'POST_FILL'))
);
CREATE TABLE "fill_plan_confirmations" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "account_id" TEXT NOT NULL,
    "application_workspace_id" TEXT NOT NULL,
    "plan_hash" TEXT NOT NULL,
    "approval_id" TEXT NOT NULL,
    "approval_binding_hash" TEXT NOT NULL,
    "actor" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("id")
);
CREATE TABLE "fill_plan_mapping_choices" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "account_id" TEXT NOT NULL,
    "application_workspace_id" TEXT NOT NULL,
    "observation_id" TEXT NOT NULL,
    "page_field_key" TEXT NOT NULL,
    "field_fingerprint" TEXT NOT NULL,
    "answer_key" TEXT,
    "choice" TEXT NOT NULL,
    "actor" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("id"),
    CHECK (choice IN ('MAP', 'NEW_QUESTION'))
);
CREATE TABLE "fill_plans" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "account_id" TEXT NOT NULL,
    "application_workspace_id" TEXT NOT NULL,
    "plan_hash" TEXT NOT NULL,
    "approval_id" TEXT NOT NULL,
    "approval_binding_hash" TEXT NOT NULL,
    "observation_id" TEXT NOT NULL,
    "plan_json" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("plan_hash"),
    UNIQUE ("id")
);
CREATE TABLE "fill_quarantine_events" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "fill_run_id" TEXT NOT NULL,
    "phase" TEXT NOT NULL,
    "ruleset_hash" TEXT,
    "action_index" BIGINT,
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("id"),
    CHECK (phase IN ('PRELOAD_INSTALLED', 'RELOADED', 'TOTAL_VERIFIED', 'VERIFIED_BEFORE_ACTION', 'LOST'))
);
CREATE TABLE "fill_results" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "fill_run_id" TEXT NOT NULL,
    "result_hash" TEXT NOT NULL,
    "result_json" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("fill_run_id"),
    UNIQUE ("id")
);
CREATE TABLE "fill_run_events" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "fill_run_id" TEXT NOT NULL,
    "event" TEXT NOT NULL,
    "reason" TEXT,
    "detail_json" TEXT NOT NULL DEFAULT '{}',
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("id"),
    CHECK (event IN ('OBSERVING', 'PLAN_PROPOSED', 'PLAN_NEEDS_REVIEW', 'UNSUPPORTED_FORM', 'REVALIDATING', 'QUARANTINE_ACTIVE', 'FILLING', 'FINAL_VALIDATING', 'FILLED_AWAITING_SUBMISSION', 'FILL_STOPPED', 'FILLED_CONTEXT_UNVERIFIED')),
    CHECK (reason IS NULL OR reason IN ('DELTA_OPENED', 'UNSUPPORTED_FORM', 'STRUCTURE_CHANGED', 'STRUCTURE_UNSTABLE', 'OBSERVATION_MISMATCH', 'OMIT_FIELD_NOT_BLANK', 'PREFILLED_VALUE_CONFLICT', 'TARGET_CHANGED', 'READBACK_MISMATCH', 'FIELD_VALIDITY_FAILED', 'FIELD_VALUE_REVERTED', 'ATTACH_LOCAL_MISMATCH', 'SIBLING_EMPLOYER_CONTEXT_OPEN', 'PERMISSIONS_MISSING', 'QUARANTINE_RULESET_CHANGED', 'QUARANTINE_LOST', 'SUBMIT_ATTEMPT_OBSERVED', 'NAVIGATION_ATTEMPT_OBSERVED', 'GRANT_REFUSED', 'GRANT_EXPIRED', 'AUTHORITY_REDUCED', 'APPROVAL_NOT_EFFECTIVE', 'PLAN_CONFIRMATION_STALE', 'ENVELOPE_EXPIRED', 'WRITE_OUTCOME_UNKNOWN', 'EXECUTOR_LOST', 'EXECUTION_CONTEXT_CLOSED'))
);
CREATE TABLE "fill_run_grant_bindings" (
    "seq" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "id" TEXT NOT NULL,
    "fill_run_id" TEXT NOT NULL,
    "grant_id" TEXT NOT NULL,
    "approval_id" TEXT NOT NULL,
    "approval_binding_hash" TEXT NOT NULL,
    "plan_hash" TEXT NOT NULL,
    "structure_fingerprint" TEXT NOT NULL,
    "observation_fingerprint" TEXT NOT NULL,
    "ruleset_hash" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    PRIMARY KEY ("seq"),
    UNIQUE ("fill_run_id"),
    UNIQUE ("id")
);
CREATE TABLE "fill_run_leases" (
    "fill_run_id" TEXT NOT NULL,
