CREATE TABLE "onboarding_progress" (
    "account_id" TEXT NOT NULL,
    "walkthrough_id" TEXT NOT NULL,
    "walkthrough_version" BIGINT NOT NULL,
    "status" TEXT NOT NULL,
    "current_step_index" BIGINT NOT NULL,
    "dismissal_reason" TEXT,
    "started_at" TEXT,
    "last_interacted_at" TEXT NOT NULL,
    "completed_at" TEXT,
    "times_completed" BIGINT NOT NULL DEFAULT 0,
    "times_started" BIGINT NOT NULL DEFAULT 0,
    "updated_at" TEXT NOT NULL,
    "rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    PRIMARY KEY ("account_id", "walkthrough_id"),
    CHECK (walkthrough_version >= 1),
    CHECK (status IN ('not_started', 'in_progress', 'completed', 'skipped')),
    CHECK (current_step_index >= 0),
    CHECK (dismissal_reason IS NULL OR dismissal_reason IN ('skip', 'dont_show_again', 'close')),
    CHECK (times_completed >= 0),
    CHECK (times_started >= 0)
);
