CREATE TABLE "policy_decisions" (
    "id" TEXT NOT NULL,
    "workspace_id" TEXT NOT NULL,
    "stage" TEXT NOT NULL,
    "source_artifact_id" TEXT NOT NULL,
    "review_item_type" TEXT NOT NULL,
    "subject_key" TEXT NOT NULL,
    "domain_item_id" TEXT,
    "outcome" TEXT NOT NULL,
    "policy_version" TEXT NOT NULL,
    "policy_fingerprint" TEXT NOT NULL,
    "evidence_ids" TEXT NOT NULL,
    "supported_facts" TEXT NOT NULL,
    "recorded_gaps" TEXT NOT NULL,
    "reason_code" TEXT NOT NULL,
    "reason" TEXT NOT NULL,
    "confidence" TEXT,
    "blocking" BIGINT NOT NULL,
    "created_at" TEXT NOT NULL,
    "rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    PRIMARY KEY ("id"),
    UNIQUE ("workspace_id", "stage", "source_artifact_id", "review_item_type", "subject_key", "policy_fingerprint"),
    CHECK (stage IN ('understanding', 'fit', 'application_intelligence', 'content')),
    CHECK (outcome IN ( 'AUTO_PROCEED', 'AUTO_PROCEED_WITH_GAPS', 'AUTO_OMIT', 'AUTO_REJECT', 'REQUIRE_USER', 'NOT_APPLICABLE' )),
    CHECK (blocking IN (0, 1))
);
CREATE TABLE "profile_source_entries" (
    "account_id" TEXT NOT NULL,
    "entry_id" TEXT NOT NULL,
