    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    PRIMARY KEY ("account_id", "entry_id"),
    UNIQUE ("account_id", "source_path", "entry_kind", "fingerprint", "occurrence"),
