-- Triggers
CREATE FUNCTION jobsearch_raise() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
    RAISE EXCEPTION USING MESSAGE = TG_ARGV[0], ERRCODE = '23000';
END
$fn$;

CREATE FUNCTION trgfn_accounts_owned_aggregate_delete_60d49d77() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
    IF EXISTS (SELECT 1 FROM workspaces WHERE account_id = OLD.id) OR EXISTS (SELECT 1 FROM search_workspaces WHERE account_id = OLD.id) OR EXISTS (SELECT 1 FROM application_document_versions WHERE account_id = OLD.id) OR EXISTS (SELECT 1 FROM reusable_application_documents WHERE account_id = OLD.id) THEN
        RAISE EXCEPTION USING MESSAGE = 'account owns application data', ERRCODE = '23000';
    END IF;
    RETURN OLD;
END
$fn$;
