CREATE FUNCTION trgfn_search_workspaces_account_insert_dba830d9() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM accounts WHERE id = NEW.account_id) THEN
        RAISE EXCEPTION USING MESSAGE = 'search workspace account does not exist', ERRCODE = '23000';
    END IF;
    RETURN NEW;
END
$fn$;
