CREATE FUNCTION trgfn_search_workspaces_account_update_7fdcaef7() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
    IF NEW.account_id <> OLD.account_id THEN
        RAISE EXCEPTION USING MESSAGE = 'search workspace ownership is immutable', ERRCODE = '23000';
    END IF;
    RETURN NEW;
END
$fn$;
